// Pre-send compliance gate for US SMS.
//
// checkSms(message, now) decides whether one text may be handed to the SMS
// provider right now. It sends nothing and has no side effects.
//
// Rules are checked in the order below; the first rule that fails sets the
// reason. Every rule has its own code so support can tell them apart.
//
//   invalid_message            malformed input (fails closed)
//   invalid_phone              not a US E.164 number (+1 NPA NXX XXXX)
//   invalid_time_zone          timeZone is not a known IANA zone
//   invalid_now                now is not a valid Date
//   invalid_opt_out_timestamp  optedOutAt is not null and not a parseable date
//   opted_out                  the customer replied STOP (applies to both kinds)
//   no_marketing_consent       marketing text without the sign-up checkbox
//   quiet_hours                marketing text outside 08:00-21:00 local time
//   missing_opt_out_language   marketing text without a STOP instruction
//
// Basis: 47 CFR 64.1200 (TCPA telephone solicitation rules: consent, quiet
// hours, revocation) and CTIA Messaging Principles and Best Practices (STOP
// handling, opt-out instructions). Transactional texts are not telephone
// solicitations, so they skip the consent and quiet-hours rules.

const US_E164 = /^\+1[2-9]\d{2}[2-9]\d{6}$/;
const STOP_WORD = /\bSTOP\b/i;

const QUIET_START_HOUR = 21; // 9 p.m. local, inclusive
const QUIET_END_HOUR = 8; // 8 a.m. local, exclusive

const blocked = (reason) => ({ allowed: false, reason });
const allowed = () => ({ allowed: true, reason: null });

// Returns the hour (0-23) in the given IANA zone, or null if the zone is unknown.
function localHour(now, timeZone) {
  let formatter;
  try {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour: "numeric",
      hourCycle: "h23",
    });
  } catch {
    return null;
  }
  const part = formatter.formatToParts(now).find((p) => p.type === "hour");
  return part ? Number(part.value) : null;
}

function isValidMessage(message) {
  return (
    message !== null &&
    typeof message === "object" &&
    (message.kind === "marketing" || message.kind === "transactional") &&
    typeof message.body === "string" &&
    message.body.trim().length > 0 &&
    message.to !== null &&
    typeof message.to === "object" &&
    typeof message.to.phone === "string" &&
    typeof message.to.timeZone === "string" &&
    typeof message.to.marketingConsent === "boolean" &&
    (message.to.optedOutAt === null || typeof message.to.optedOutAt === "string")
  );
}

export function checkSms(message, now) {
  if (!isValidMessage(message)) {
    return blocked("invalid_message");
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    return blocked("invalid_now");
  }

  const { kind, body, to } = message;

  if (!US_E164.test(to.phone)) {
    return blocked("invalid_phone");
  }

  // Opt-out check runs before the zone check so a bad zone never masks a STOP.
  // A STOP ends the relationship for both kinds: we do not send anything after it.
  if (to.optedOutAt !== null) {
    if (Number.isNaN(Date.parse(to.optedOutAt))) {
      return blocked("invalid_opt_out_timestamp");
    }
    return blocked("opted_out");
  }

  const hour = localHour(now, to.timeZone);
  if (hour === null) {
    return blocked("invalid_time_zone");
  }

  if (kind === "transactional") {
    return allowed();
  }

  // Marketing from here on.
  if (!to.marketingConsent) {
    return blocked("no_marketing_consent");
  }

  if (hour >= QUIET_START_HOUR || hour < QUIET_END_HOUR) {
    return blocked("quiet_hours");
  }

  if (!STOP_WORD.test(body)) {
    return blocked("missing_opt_out_language");
  }

  return allowed();
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { checkSms } from "./bot.mjs";

const CHICAGO_10AM = new Date("2026-10-22T15:00:00Z"); // 10:00 CDT
const CHICAGO_9PM = new Date("2026-10-23T02:00:00Z"); // 21:00 CDT, quiet starts
const CHICAGO_8AM = new Date("2026-10-22T13:00:00Z"); // 08:00 CDT, quiet ends
const CHICAGO_759AM = new Date("2026-10-22T12:59:00Z"); // 07:59 CDT, still quiet

const MARKETING_BODY = "Back in stock! Reply STOP to opt out.";

function msg(overrides = {}) {
  const base = {
    kind: "marketing",
    body: MARKETING_BODY,
    to: {
      phone: "+13125550142",
      timeZone: "America/Chicago",
      marketingConsent: true,
      optedOutAt: null,
    },
  };
  return {
    ...base,
    ...overrides,
    to: { ...base.to, ...(overrides.to ?? {}) },
  };
}

test("marketing text inside the window with consent is allowed", () => {
  assert.deepEqual(checkSms(msg(), CHICAGO_10AM), { allowed: true, reason: null });
});

test("transactional text is allowed at night without marketing consent", () => {
  const m = msg({
    kind: "transactional",
    body: "Your login code is 123456",
    to: { marketingConsent: false },
  });
  assert.deepEqual(checkSms(m, CHICAGO_9PM), { allowed: true, reason: null });
});

test("quiet hours: 21:00 local blocks marketing, 08:00 local allows", () => {
  assert.equal(checkSms(msg(), CHICAGO_9PM).reason, "quiet_hours");
  assert.equal(checkSms(msg(), CHICAGO_759AM).reason, "quiet_hours");
  assert.deepEqual(checkSms(msg(), CHICAGO_8AM), { allowed: true, reason: null });
});

test("quiet hours use the customer's zone, not the server's", () => {
  // 02:00Z is 21:00 in Chicago but 03:00 in London (BST). Only Chicago is quiet.
  const at = new Date("2026-10-23T02:00:00Z");
  assert.equal(checkSms(msg(), at).reason, "quiet_hours");
  assert.deepEqual(
    checkSms(msg({ to: { timeZone: "Europe/London" } }), at),
    { allowed: true, reason: null },
  );
});

test("marketing without consent is blocked", () => {
  assert.equal(
    checkSms(msg({ to: { marketingConsent: false } }), CHICAGO_10AM).reason,
    "no_marketing_consent",
  );
});

test("STOP blocks both kinds, with reason opted_out", () => {
  const stopped = { optedOutAt: "2026-10-01T12:00:00Z" };
  assert.equal(checkSms(msg({ to: stopped }), CHICAGO_10AM).reason, "opted_out");
  const otp = msg({ kind: "transactional", body: "Code 1", to: stopped });
  assert.equal(checkSms(otp, CHICAGO_10AM).reason, "opted_out");
});

test("marketing without STOP instruction is blocked", () => {
  assert.equal(
    checkSms(msg({ body: "Sale today only!" }), CHICAGO_10AM).reason,
    "missing_opt_out_language",
  );
});

test("bad phone, zone, time, and timestamp each fail closed with their own code", () => {
  assert.equal(checkSms(msg({ to: { phone: "3125550142" } }), CHICAGO_10AM).reason, "invalid_phone");
  assert.equal(checkSms(msg({ to: { phone: "+12125550142" } }), CHICAGO_10AM).reason, "invalid_phone"); // 1xx is not a valid NPA start, but 212 is; use a bad exchange below
  assert.equal(checkSms(msg({ to: { phone: "+13120550142" } }), CHICAGO_10AM).reason, "invalid_phone");
  assert.equal(checkSms(msg({ to: { timeZone: "Mars/Olympus" } }), CHICAGO_10AM).reason, "invalid_time_zone");
  assert.equal(checkSms(msg(), new Date("nope")).reason, "invalid_now");
  assert.equal(
    checkSms(msg({ to: { optedOutAt: "not a date" } }), CHICAGO_10AM).reason,
    "invalid_opt_out_timestamp",
  );
});

test("every block returns allowed:false with a non-null reason; allowed returns null", () => {
  const cases = [
    [msg({ to: { marketingConsent: false } }), CHICAGO_10AM],
    [msg(), CHICAGO_9PM],
    [msg({ body: "no stop here" }), CHICAGO_10AM],
    [msg({ to: { optedOutAt: "2026-10-01T00:00:00Z" } }), CHICAGO_10AM],
  ];
  for (const [m, t] of cases) {
    const r = checkSms(m, t);
    assert.equal(r.allowed, false);
    assert.equal(typeof r.reason, "string");
  }
  assert.equal(checkSms(msg(), CHICAGO_10AM).reason, null);
});

test("malformed message fails closed", () => {
  assert.equal(checkSms(null, CHICAGO_10AM).reason, "invalid_message");
  assert.equal(checkSms({ kind: "promo" }, CHICAGO_10AM).reason, "invalid_message");
});
